from common import *
import io
m=load(); out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 04 — first-pass results (public data only)\n")
P("Generated by `p04.py` 2026-11-26. Sources: CHR supplemental release (25 Mar 2026): low birth weight (NCHS natality, 2018-2024), teen births (2018-2024), infant mortality (NCHS linked files, 2017-2023), race-specific where CHR publishes; CHR 2025 annual release for demographics/poverty/segregation; CDC PLACES 2025 release. Race-specific county values are only those CHR published (unreliable/suppressed excluded). MSTAHRS and CDC WONDER queries are [PENDING] (interactive query systems).\n")
P("## A. Availability (82 counties)\n")
av=pd.DataFrame([[l,m[c].notna().sum()] for l,c in [('LBW % all','lbw_pct'),('LBW % White','lbw_white'),('LBW % Black','lbw_black'),('Teen birth rate all','teen_birth_rate'),('Teen birth White','teen_white'),('Teen birth Black','teen_black'),('Infant mortality all','infmort_rate'),('Infant mortality White','infmort_white'),('Infant mortality Black','infmort_black')]],columns=['Measure','Counties with published value'])
P(av.to_markdown(index=False)); P()
P("## B. Black vs White (counties with both published)\n")
rows=[]
for lab,b,w in [('Low birth weight, %','lbw_black','lbw_white'),('Teen births per 1,000 females 15-19','teen_black','teen_white'),('Infant deaths per 1,000 live births','infmort_black','infmort_white')]:
    d=m[[b,w]].dropna()
    if len(d)<6: rows.append([lab,len(d),np.nan,np.nan,np.nan,np.nan,np.nan]); continue
    diff=d[b]-d[w]; rows.append([lab,len(d),d[w].median(),d[b].median(),diff.median(),(diff>0).sum(),stats.wilcoxon(d[b],d[w]).pvalue])
P(pd.DataFrame(rows,columns=['Measure','n counties','White median','Black median','Median diff (B-W)','Counties Black > White','Wilcoxon p']).to_markdown(index=False,floatfmt='.3g')); P()
# state rows from CHR
s=pd.read_csv('raw/chr_supp2026.csv',dtype=str,low_memory=False); st=s[(s.statecode=='28')&(s.countycode=='000')].iloc[0]
P("## C. Mississippi state values (CHR supplemental release)\n")
rows=[]
for lab,v in [('Low birth weight % (2018-24)','v037'),('Teen births per 1,000 (2018-24)','v014'),('Infant mortality per 1,000 (2017-23)','v129')]:
    def g(c): 
        x=pd.to_numeric(st.get(c),errors='coerce'); return x
    sc=100 if 'v037' in v else 1
    rows.append([lab,g(v+'_rawvalue')*sc,g(v+'_race_white')*sc,g(v+'_race_black')*sc])
P(pd.DataFrame(rows,columns=['Measure','All','White','Black']).to_markdown(index=False,floatfmt='.2f')); P()
P("## D. County correlates of overall low birth weight and teen births (Spearman)\n")
rows=[]
for y,ly in [('lbw_pct','LBW %'),('teen_birth_rate','Teen birth rate')]:
    for x,lx in [('child_poverty','Child poverty %'),('pcp_per100k','PCP per 100k'),('uninsured_pct','Uninsured %'),('pct_black_nh','% Black NH'),('nonmetro','Nonmetro'),('dra_county','DRA (Delta region) county'),('segregation_bw','B/W segregation'),('hs_completion','HS completion %'),('median_hh_income','Median HH income')]:
        n,r,p=spearman(m[x],m[y]); rows.append([ly,lx,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','Predictor','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("## E. OLS (HC3): low birth weight % ~ county context\n")
m['pcp10']=m.pcp_per100k/10; m['pov10']=m.child_poverty/10; m['black10']=m.pct_black_nh/10
for lab,xs in [('Model 1',['pov10','pcp10']),('Model 2: + %Black, nonmetro, DRA',['pov10','pcp10','black10','nonmetro','dra_county'])]:
    mod,t,n=ols(m,'lbw_pct',xs); P(f"**{lab}** (n={n}, R2={mod.rsquared:.2f}); LBW in percentage points; poverty and %Black per 10 pts; PCP per 10,000\n"); P(t.round(3).to_markdown()); P()
P("## F. Black–White LBW gap (percentage points) vs county context\n")
m['gap_lbw']=m.lbw_black-m.lbw_white
rows=[]
for x,lx in [('segregation_bw','B/W segregation'),('child_poverty','Child poverty %'),('child_poverty_black','Black child poverty %'),('pcp_per100k','PCP per 100k'),('pct_black_nh','% Black NH'),('nonmetro','Nonmetro')]:
    n,r,p=spearman(m[x],m.gap_lbw); rows.append([lx,n,r,p])
P(pd.DataFrame(rows,columns=['Predictor','n counties','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
mod,t,n=ols(m,'gap_lbw',['segregation_bw','child_poverty_black','pcp10','nonmetro']); P(f"OLS gap_lbw ~ segregation + Black child poverty % + PCP/10k + nonmetro (n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
d=m[['lbw_black','lbw_white']].dropna()
P(f"- Counties with both LBW values: {len(d)}; Black LBW is higher in {(d.lbw_black>d.lbw_white).sum()}; and the lowest Black county LBW ({d.lbw_black.min():.1f}%) vs highest White ({d.lbw_white.max():.1f}%).")
P("\nNote: ecological, descriptive; CHR race-specific rates are suppressed/unreliable in small counties so results over-represent larger counties.")
cols=['fips','county','population','nonmetro','dra_county','rucc2023','pct_black_nh','child_poverty','child_poverty_black','uninsured_pct','pcp_per100k','segregation_bw','lbw_pct','lbw_white','lbw_black','teen_birth_rate','teen_white','teen_black','infmort_rate','infmort_white','infmort_black']
m[cols].to_csv('results/p04/p04_county_dataset.csv',index=False)
open('results/p04/p04_results.md','w').write(out.getvalue()); print(out.getvalue())
